const Default = () => {
  const [pressed, setPressed] = useState(false);
  return (
    <Toggle
      pressed={pressed}
      onPressedChange={setPressed}
      offState="Off"
      onState="On"
    />
  );
};

const AsSwitch = () => {
  const [pressed, setPressed] = useState(false);
  return (
    <Toggle
      isSwitch
      pressed={pressed}
      onPressedChange={setPressed}
      offState="Off"
      onState="On"
    />
  );
};

const WithContentChildren = () => {
  const [pressed, setPressed] = useState(false);
  return (
    <Toggle
      pressed={pressed}
      onPressedChange={setPressed}
    >
      <span>Child Content</span>
    </Toggle>
  );
};

const WithClasses = () => {
  const [pressed, setPressed] = useState(false);
  return (
    <Toggle
      pressed={pressed}
      onPressedChange={setPressed}
      classes="px-4 py-2 rounded-full"
      offStateClasses="bg-gray-200 text-gray-800"
      onStateClasses="bg-blue-600 text-white"
      offState="Off"
      onState="On"
    />
  );
};

const Disabled = () => {
  const [pressed, setPressed] = useState(false);
  return (
    <Toggle
      pressed={pressed}
      onPressedChange={setPressed}
      disabled
      offState="Off"
      onState="On"
    />
  );
};

const Expandible = () => {
  const [pressed, setPressed] = useState(false);
  return (
    <Toggle
      isExpandible
      pressed={pressed}
      onPressedChange={setPressed}
      offState="Collapsed"
      onState="Expanded"
    />
  );
};

visuallyHiddenTitle.description:
Visually hidden title for screen readers.
When provided, renders a visually hidden label before the description text.
@deprecated Use aria-label on parent or wrapper instead

